window.HYDRO_DEMO_QUESTIONS.push(...[{"id":"V2-C2-D201-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-12x\\) sur [-4,4], quels points réalisent les extrema globaux ?","a":["Maximum 16 en -2 et 4 ; minimum -16 en -4 et 2.","Maximum 16 seulement en -2 ; minimum -16 seulement en 2.","Maximum 64 en 4 ; minimum -64 en -4.","Maximum 16 en 2 et 4 ; minimum -16 en -4 et -2."],"correct":0,"why":"Comparer les valeurs aux deux points stationnaires et aux deux bornes.","active":true,"family":"V2-C2-D201"},{"id":"V2-C2-D201-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-3x\\) sur [0,3], où sont atteints les extrema globaux ?","a":["Minimum 0 en 0 ; maximum 2 en 1.","Minimum -2 en 1 ; maximum 0 en 0.","Minimum -2 en 1 ; aucun maximum.","Minimum -2 en 1 ; maximum 18 en 3."],"correct":3,"why":"Comparer g(0)=0, g(1)=-2 et g(3)=18.","active":true,"family":"V2-C2-D201"},{"id":"V2-C2-D201-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(h(x)=-x^3+12x\\) sur [0,5], quels sont le maximum et le minimum globaux ?","a":["Maximum 16 en 2 ; minimum 0 en 0.","Maximum 60 en 5 ; minimum -16 en 2.","Maximum 16 en 2 ; minimum -65 en 5.","Maximum 0 en 0 ; minimum -65 en 5."],"correct":2,"why":"h'=12-3x² s'annule en 2 ; comparer h(0), h(2) et h(5).","active":true,"family":"V2-C2-D201"},{"id":"V2-C2-D202-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Le débit d'une rivière \\(G(t)=8+3te^{-2t}\\) est étudiée pour t≥0. Quel couple donne l'instant du maximum et sa valeur exacte ?","a":["\\(t=2,\\ G_{\\max}=8+6e^{-4}\\)","\\(t=1/2,\\ G_{\\max}=8+3/(2e)\\)","\\(t=1/2,\\ G_{\\max}=8+3e/2\\)","\\(t=0,\\ G_{\\max}=8\\)"],"correct":1,"why":"G'=3(1-2t)e^-2t change de signe de + à - en 1/2.","active":true,"family":"V2-C2-D202"},{"id":"V2-C2-D202-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"L'indice de ruissellement est \\(G(t)=4t^2e^{-t}\\) pour t≥0. Quel est son maximum global et pourquoi t=0 n'est-il pas maximiseur ?","a":["Maximum \\(4e^{-1}\\) en t=1 ; G décroît à partir de 1.","Maximum \\(16e^{-2}\\) en t=2 ; G croît entre 0 et 2.","Maximum 0 en t=0, car G'(0)=0.","Maximum \\(16e^2\\) en t=2."],"correct":1,"why":"G'=4t(2-t)e^-t.","active":true,"family":"V2-C2-D202"},{"id":"V2-C2-D202-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(G(t)=12+6te^{-3t}\\) sur t≥0, quelle est l'amplitude maximale de l'excès G(t)-12 ?","a":["\\(2/e\\), atteinte en t=1/3.","\\(6/e\\), atteinte en t=1.","\\(2e\\), atteinte en t=1/3.","\\(6\\), atteinte en t=0."],"correct":0,"why":"Dériver 6te^-3t puis évaluer au point t=1/3.","active":true,"family":"V2-C2-D202"},{"id":"V2-C2-D203-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une température en degrés Celsius suit \\(G(t)=18+4\\sin(\\pi t/6)\\), t en heures. Quelle vitesse instantanée possède-t-elle au temps t=0 ?","a":["4 °C/h.","\\(\\pi/6\\) °C/h.","0 °C/h.","\\(2\\pi/3\\) °C/h."],"correct":3,"why":"G'(t)=(2π/3)cos(πt/6).","active":true,"family":"V2-C2-D203"},{"id":"V2-C2-D203-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la température \\(G(t)=20+6\\cos(\\pi t/12)\\), à quel instant de [0,24] le taux instantané G' est-il minimal ?","a":["0 h ; G' vaut -π/2.","12 h ; G' vaut 0.","6 h ; G' vaut -π/2.","18 h ; G' vaut +π/2."],"correct":2,"why":"G'=-(π/2)sin(πt/12) atteint sa valeur minimale en t=6.","active":true,"family":"V2-C2-D203"},{"id":"V2-C2-D203-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une température périodique en degrés Celsius est donnée par \\(G(t)=30+9\\sin(\\pi t/18)\\). Quelle expression de G' et sa valeur à t=9 sont exactes ?","a":["\\(G'(t)=9\\cos(\\pi t/18)\\) et G'(9)=0.","\\(G'(t)=-(\\pi/2)\\sin(\\pi t/18)\\) et G'(9)=-π/2.","\\(G'(t)=(\\pi/2)\\cos(\\pi t/18)\\) et G'(9)=0.","\\(G'(t)=(\\pi/18)\\cos(\\pi t/18)\\) et G'(9)=1."],"correct":2,"why":"La règle de chaîne donne 9π/18=π/2, puis cos(π/2)=0.","active":true,"family":"V2-C2-D203"},{"id":"V2-C2-D204-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"La biomasse d'une parcelle suit \\(G(t)=40-30e^{-0,2t}\\) pour t≥0. Que révèlent les signes de G' et G'' ?","a":["G diminue et sa vitesse de diminution augmente.","G augmente et sa vitesse de croissance diminue.","G augmente et sa vitesse de croissance augmente.","G diminue mais sa vitesse est constante."],"correct":1,"why":"G'=6e^-0,2t>0 et G''=-1,2e^-0,2t<0.","active":true,"family":"V2-C2-D204"},{"id":"V2-C2-D204-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour un stock de polluant \\(G(t)=15+20e^{-0,5t}\\), quelle interprétation des dérivées est rigoureuse ?","a":["G décroît, mais le taux de diminution en valeur absolue s'atténue.","G décroît et sa diminution s'accélère.","G croît à vitesse décroissante.","G est constante car sa dérivée tend vers zéro."],"correct":0,"why":"G'=-10e^-0,5t<0, G''=5e^-0,5t>0.","active":true,"family":"V2-C2-D204"},{"id":"V2-C2-D204-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de stockage d'eau \\(G(t)=60(1-e^{-t/3})\\) représente une accumulation. Quelle description combine variations et convexité ?","a":["Croissante et convexe ; sa vitesse augmente.","Décroissante et convexe ; sa vitesse est négative.","Croissante et affine ; sa vitesse est constante.","Croissante et concave ; sa vitesse tend vers zéro."],"correct":3,"why":"G'=20e^-t/3>0 et G''=-(20/3)e^-t/3<0.","active":true,"family":"V2-C2-D204"},{"id":"V2-C2-D205-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une concentration de polluant \\(G(t)=30e^{-0,3t}\\) modélise une diminution. Quel modèle affine local permet d'approcher G(t+h) pour h petit ?","a":["\\(G(t)(1+0,3h)\\)","\\(G(t)-0,3/h\\)","\\(G(t)e^{0,3h}\\)","\\(G(t)(1-0,3h)\\)"],"correct":3,"why":"G'=-0,3G et G(t+h)≈G(t)+hG'(t).","active":true,"family":"V2-C2-D205"},{"id":"V2-C2-D205-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la concentration de polluant \\(G(t)=80e^{-0,25t}\\), une mesure donne G(t)=40 à un certain instant. Quelle approximation locale de G(t+0,2) est correcte ?","a":["42 unités.","39,8 unités.","38 unités.","30 unités."],"correct":2,"why":"G'=-0,25G=-10 à cet instant ; ajouter -10×0,2.","active":true,"family":"V2-C2-D205"},{"id":"V2-C2-D205-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant approxime G(t+h) par G(t)(1+kh) pour \\(G(t)=G_0e^{-kt}\\), k>0 et G0>0. Quelle erreur commet-il ?","a":["Il utilise une approximation du premier ordre alors que le taux est constant.","Il prévoit une hausse pour h>0 alors que G'=-kG<0 ; le signe devant kh doit être négatif.","Il devrait remplacer k par 1/k, sans changer de signe.","Il doit ajouter h² à G(t)."],"correct":1,"why":"La dérivée relative vaut -k.","active":true,"family":"V2-C2-D205"},{"id":"V2-C2-D206-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=\\vert x-1\\vert\\) sur [0,2], quelle hypothèse empêche d'invoquer Rolle malgré l'égalité des images aux bornes ?","a":["f n'est pas dérivable en x=1, qui est intérieur.","f n'est pas continue au point 1.","f(0) et f(2) sont distinctes.","f est strictement positive sur le segment."],"correct":0,"why":"Les dérivées latérales valent -1 et 1.","active":true,"family":"V2-C2-D206"},{"id":"V2-C2-D206-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"On considère \\(f(x)=\\sqrt{x}\\) sur [0,4]. Un étudiant refuse d'appliquer le TAF parce que f' n'existe pas en 0. Quelle réponse est exacte ?","a":["Le TAF s'applique : la dérivabilité n'est exigée que sur ]0,4[.","Le TAF est impossible dès qu'une dérivée n'existe pas à une borne.","Le TAF exige f(0)=f(4), ce qui est faux.","Le TAF exige une dérivée seconde continue."],"correct":0,"why":"f est continue sur [0,4] et dérivable sur ]0,4[.","active":true,"family":"V2-C2-D206"},{"id":"V2-C2-D206-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=\\sqrt{1-x^2}\\) sur [-1,1], quelle conclusion est correcte ?","a":["Rolle ne s'applique pas car f' n'existe pas aux bornes.","Rolle s'applique et impose f'(x)=0 pour tout x.","Rolle exige que f soit strictement monotone.","Rolle s'applique et f'(0)=0, malgré les tangentes verticales aux bornes."],"correct":3,"why":"Les valeurs aux bornes sont nulles et la fonction est dérivable à l'intérieur.","active":true,"family":"V2-C2-D206"},{"id":"V2-C2-D207-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\ln x-x/4\\) sur x>0. Quel point réalise son maximum global et quelle est sa valeur ?","a":["\\(x=1/4,\\ f(1/4)=\\ln(1/4)-1/16\\)","\\(x=4,\\ f(4)=\\ln4\\)","\\(x=4,\\ f(4)=\\ln4-1\\)","Aucun maximum puisque le domaine est ouvert."],"correct":2,"why":"f'=1/x-1/4 change de + à - en 4.","active":true,"family":"V2-C2-D207"},{"id":"V2-C2-D207-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=2\\ln x-x\\) sur ]0,+∞[, quelle analyse est complète ?","a":["Minimum global en 2, de valeur 2 ln 2-2 ; f est convexe.","Maximum global en 2, de valeur 2 ln 2-2 ; f est strictement concave.","Maximum global en 1, de valeur -1 ; f est concave.","Aucun extremum, car f diverge près de zéro."],"correct":1,"why":"f'=2/x-1 et f''=-2/x²<0.","active":true,"family":"V2-C2-D207"},{"id":"V2-C2-D207-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de rendement est \\(R(t)=\\ln(1+t)-t/3\\) pour t≥0. Quelle est sa valeur maximale ?","a":["\\(\\ln4-1\\), atteinte en t=3.","\\(\\ln3-2/3\\), atteinte en t=2.","\\(\\ln2-1/3\\), atteinte en t=1.","0, atteinte en t=0."],"correct":1,"why":"R'=1/(1+t)-1/3 s'annule en 2 et change de signe.","active":true,"family":"V2-C2-D207"},{"id":"V2-C2-D208-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une fonction \\(f(x)=\\frac{x}{x+3}\\) est étudiée sur x>0. Quelle conclusion combine le signe de ses deux premières dérivées ?","a":["Croissante et strictement concave.","Décroissante et strictement convexe.","Croissante et strictement convexe.","Décroissante et strictement concave."],"correct":0,"why":"f'=3/(x+3)² et f''=-6/(x+3)³.","active":true,"family":"V2-C2-D208"},{"id":"V2-C2-D208-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=\\frac{5x}{2+x}\\) sur [0,+∞[, quelle affirmation sur sa croissance est correcte ?","a":["Elle augmente sans borne, et son taux de croissance augmente.","Elle diminue vers zéro, et son taux de croissance augmente.","Elle est constante à partir de x=2.","Elle augmente vers 5, et son taux de croissance diminue."],"correct":3,"why":"f'=10/(x+2)²>0 et f''=-20/(x+2)³<0.","active":true,"family":"V2-C2-D208"},{"id":"V2-C2-D208-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une grandeur \\(G(t)=\\frac{20t}{t+4}\\) a une valeur limite de 20 unités. Quelles dérivées justifient une saturation progressive ?","a":["\\(G'=20/(t+4)>0\\) et \\(G''=0\\).","\\(G'=-80/(t+4)^2<0\\) et \\(G''>0\\).","\\(G'=80/(t+4)^2>0\\) et \\(G''=-160/(t+4)^3<0\\).","\\(G'=20\\) et \\(G''=0\\)."],"correct":2,"why":"Appliquer la règle du quotient puis dériver une seconde fois.","active":true,"family":"V2-C2-D208"},{"id":"V2-C2-D209-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Si f est trois fois dérivable et que \\(\\vert f^{(3)}(x)\\vert\\le M\\) sur le segment reliant a et a+h, quelle borne usuelle de Taylor-Lagrange majore l'erreur du polynôme d'ordre 2 ?","a":["\\(\\frac M2\\vert h\\vert^2\\)","\\(\\frac M{24}\\vert h\\vert^4\\)","\\(\\frac M6\\vert h\\vert^3\\)","\\(\\frac M6\\vert h\\vert^2\\)"],"correct":2,"why":"Le reste d'ordre 2 est proportionnel à la troisième dérivée et à h³/3!.","active":true,"family":"V2-C2-D209"},{"id":"V2-C2-D209-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=2x^3-x\\), quelle est la majoration usuelle de l'erreur de Taylor-Lagrange d'ordre 2 lorsque h=0,1 ?","a":["0,012.","0,002.","0,02.","0,2."],"correct":1,"why":"f'''=12, donc 12×0,1³/6=0,002.","active":true,"family":"V2-C2-D209"},{"id":"V2-C2-D209-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une approximation d'ordre 2 utilise un pas h et on sait que \\(\\vert f^{(3)}\\vert\\le24\\). Quel pas maximal en valeur absolue garantit une erreur au plus 0,004 par la borne de Taylor-Lagrange ?","a":["0,1.","0,01.","0,2.","0,4."],"correct":0,"why":"Imposer 4 fois le cube du module de h ≤0,004, donc le module de h ≤0,1.","active":true,"family":"V2-C2-D209"},{"id":"V2-C2-D210-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=x^3-6x^2+9x+1\\). Quelle affirmation décrit la position du point d'inflexion par rapport aux extrema ?","a":["Inflexion en x=1, confondue avec le maximum local.","Inflexion en x=3, confondue avec le minimum local.","Aucun point d'inflexion, car f possède deux extrema.","Inflexion en x=2, entre maximum local en 1 et minimum local en 3."],"correct":3,"why":"f'=3(x-1)(x-3) et f''=6(x-2).","active":true,"family":"V2-C2-D210"},{"id":"V2-C2-D210-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-9x^2+15x\\), à quelle abscisse la pente de la tangente est-elle minimale ?","a":["\\(x=1\\), car g'(1)=0.","\\(x=5\\), car g'(5)=0.","\\(x=0\\), car g(0)=0.","\\(x=3\\), car g' est une parabole de sommet 3."],"correct":3,"why":"g'=3x²-18x+15 ; g''=6x-18 s'annule en 3.","active":true,"family":"V2-C2-D210"},{"id":"V2-C2-D210-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(h(x)=x^3+3x^2+2x\\), quelle est la pente de la tangente au point d'inflexion ?","a":["\\(0\\)","\\(1\\)","\\(-1\\)","\\(2\\)"],"correct":2,"why":"h''=6x+6 s'annule en -1 et h'(-1)=3-6+2=-1.","active":true,"family":"V2-C2-D210"},{"id":"V2-C2-D211-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une température \\(G(t)=25+5\\sin(\\pi(t-2)/12)\\) décrit un cycle de 24 h. À quel instant de [0,24] atteint-elle son maximum et quelle est sa valeur ?","a":["6 h ; 30 °C.","8 h ; 30 °C.","14 h ; 25 °C.","20 h ; 20 °C."],"correct":1,"why":"Le sinus vaut 1 pour π(t-2)/12=π/2.","active":true,"family":"V2-C2-D211"},{"id":"V2-C2-D211-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une mesure de température suit \\(G(t)=10+3\\cos(\\pi(t-4)/6)\\). À quel instant de [0,12[ atteint-elle son minimum et quelle est sa valeur ?","a":["10 h ; 7 °C.","4 h ; 13 °C.","6 h ; 7 °C.","8 h ; 10 °C."],"correct":0,"why":"Le cosinus vaut -1 pour π(t-4)/6=π.","active":true,"family":"V2-C2-D211"},{"id":"V2-C2-D211-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la température \\(G(t)=40+8\\sin(\\pi t/12)\\) sur [0,24], quel est l'intervalle de décroissance et la diminution totale sur cet intervalle ?","a":["De 6 h à 18 h ; diminution de 16 °C.","De 0 h à 12 h ; diminution de 8 °C.","De 18 h à 24 h ; diminution de 16 °C.","De 6 h à 18 h ; diminution de 8 °C."],"correct":0,"why":"Les extrema valent 48 et 32 ; le cosinus est négatif de 6 à 18.","active":true,"family":"V2-C2-D211"},{"id":"V2-C2-D212-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Calculer \\(\\lim_{x\\to0}\\frac{e^{3x}-1-3x}{x^2}\\) en identifiant le terme dominant après annulation du terme linéaire.","a":["\\(3\\)","\\(0\\)","\\(-9/2\\)","\\(9/2\\)"],"correct":3,"why":"Le DL exponentiel fournit 1+3x+9x²/2+o(x²).","active":true,"family":"V2-C2-D212"},{"id":"V2-C2-D212-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(R(h)=\\ln(1+2h)-2h\\). Quelle limite du quotient R(h)/h² traduit l'erreur quadratique de l'approximation affine ?","a":["\\(2\\)","\\(-1\\)","\\(-2\\)","\\(0\\)"],"correct":2,"why":"Le terme quadratique du logarithme vaut -(2h)²/2.","active":true,"family":"V2-C2-D212"},{"id":"V2-C2-D212-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant affirme que \\(\\lim_{x\\to0}(\\cos(3x)-1)/x^2=0\\) parce que le numérateur tend vers zéro. Quelle limite exacte réfute ce raisonnement ?","a":["\\(9/2\\)","\\(-9/2\\)","\\(-3\\)","\\(0\\)"],"correct":1,"why":"Le numérateur est équivalent à -9x²/2.","active":true,"family":"V2-C2-D212"},{"id":"V2-C2-D213-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une mesure de concentration suit \\(C(t)=50e^{-0,4t}\\). Quel polynôme de degré 2 en h approche C(h) autour de t=0 ?","a":["\\(50-20h-4h^2\\)","\\(50-20h+4h^2\\)","\\(50-0,4h+0,08h^2\\)","\\(50+20h+4h^2\\)"],"correct":1,"why":"C(0)=50, C'(0)=-20, C''(0)=8.","active":true,"family":"V2-C2-D213"},{"id":"V2-C2-D213-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un capteur est calibré par \\(R(h)=\\sqrt{1+4h}\\). Quelle approximation d'ordre 2 au voisinage de zéro tient compte de la concavité ?","a":["\\(1+2h-2h^2\\)","\\(1+2h+2h^2\\)","\\(1+4h-2h^2\\)","\\(1+2h\\) uniquement."],"correct":0,"why":"Utiliser √(1+u)=1+u/2-u²/8+o(u²).","active":true,"family":"V2-C2-D213"},{"id":"V2-C2-D213-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une grandeur suit \\(G(t)=10(1-e^{-t})\\). Quelle estimation quadratique de G(0,1) donne son DL d'ordre 2 en zéro ?","a":["1,05 unité.","1 unité.","0,05 unité.","0,95 unité."],"correct":3,"why":"G(t)=10t-5t²+o(t²), puis t=0,1.","active":true,"family":"V2-C2-D213"},{"id":"V2-C2-D214-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=x^3-3x\\), x réel. Pour quelles valeurs de m l'équation f(x)=m possède-t-elle exactement trois solutions réelles distinctes ?","a":["\\(-2\\le m\\le2\\)","\\(m>2\\)","\\(-2<m<2\\)","\\(m=2\\) uniquement."],"correct":2,"why":"Les trois branches monotones se recouvrent strictement entre les deux valeurs extrêmes.","active":true,"family":"V2-C2-D214"},{"id":"V2-C2-D214-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-12x\\), combien de solutions réelles distinctes possède g(x)=16 ?","a":["Trois, car g est de degré 3.","Une, car g(4)=16.","Deux, dont x=-2 qui est stationnaire.","Aucune, car le maximum local vaut 16."],"correct":2,"why":"g(-2)=g(4)=16 ; la branche croissante à droite traverse le niveau.","active":true,"family":"V2-C2-D214"},{"id":"V2-C2-D214-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(h(x)=x^3-3x+4\\). Combien de racines réelles distinctes possède h(x)=4, et pourquoi ?","a":["Une : h est polynomiale de degré impair.","Trois : le niveau 4 se trouve entre les valeurs 2 et 6 des extrema locaux.","Deux : h possède deux points stationnaires.","Aucune : h est positive sur R."],"correct":1,"why":"h(1)=2 et h(-1)=6, et chaque branche monotone traverse le niveau 4.","active":true,"family":"V2-C2-D214"},{"id":"V2-C2-D215-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une fonction dérivable satisfait \\(\\vert f'(x)\\vert\\le0,4\\) sur [2,7]. Quel écart maximal entre f(2) et f(7) peut-on garantir ?","a":["2 unités.","0,4 unité.","12,5 unités.","7 unités."],"correct":0,"why":"L'inégalité des accroissements finis majore l'écart par 0,4×5.","active":true,"family":"V2-C2-D215"},{"id":"V2-C2-D215-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle a un taux borné en module par 2,5 unités/h sur [1,4]. Sachant G(1)=10, quel encadrement le plus précis de G(4) est garanti ?","a":["\\([7,5;12,5]\\)","\\([10;17,5]\\)","\\([-7,5;7,5]\\)","\\([2,5;17,5]\\)"],"correct":3,"why":"Le TAF impose un écart maximal de 2,5×3=7,5.","active":true,"family":"V2-C2-D215"},{"id":"V2-C2-D215-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour une fonction dérivable dont la dérivée est comprise entre -3 et -1 sur [0,4], quelle affirmation quantitative et qualitative est certaine ?","a":["Elle croît et f(4)-f(0) appartient à [4,12].","Elle décroît et f(4)-f(0) appartient à [-3,-1].","Elle est constante si f(0)=0.","Elle décroît et f(4)-f(0) appartient à [-12,-4]."],"correct":3,"why":"Multiplier les bornes négatives de la dérivée par la longueur 4.","active":true,"family":"V2-C2-D215"},{"id":"V2-C2-F201-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soit une fonction f définie sur un intervalle ouvert contenant a. Quelle expression définit son nombre dérivé en a, lorsque cette limite existe ?","a":["\\(\\lim_{h\\to0}\\frac{f(a+h)+f(a)}h\\)","\\(\\lim_{h\\to0}[f(a+h)-f(a)]\\)","\\(\\lim_{h\\to0}\\frac{f(a+h)-f(a)}h\\)","\\(\\lim_{h\\to0}\\frac{f(a)-f(h)}h\\)"],"correct":2,"why":"Le taux d'accroissement est la variation de f divisée par la variation de la variable.","active":true,"family":"V2-C2-F201"},{"id":"V2-C2-F201-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour étudier la dérivabilité de f au point a=2, un étudiant calcule \\(\\lim_{x\\to2}\\frac{f(x)-f(2)}{x}\\). Quelle correction doit-il apporter au dénominateur ?","a":["Remplacer x par \\(x+2\\).","Remplacer x par \\(x-2\\).","Remplacer x par \\(f(x)-2\\).","Conserver x, car il tend vers 2."],"correct":1,"why":"Le dénominateur est la différence entre les deux abscisses.","active":true,"family":"V2-C2-F201"},{"id":"V2-C2-F201-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur G varie avec le temps. Quel quotient faut-il faire tendre vers une limite lorsque h tend vers zéro pour obtenir sa vitesse instantanée au temps t ?","a":["\\([G(t+h)-G(t)]/h\\)","\\([G(t+h)-G(t)]/t\\)","\\(G(t+h)/h\\)","\\([G(t+h)+G(t)]/h\\)"],"correct":0,"why":"La vitesse instantanée est la limite du taux de variation moyen.","active":true,"family":"V2-C2-F201"},{"id":"V2-C2-F202-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"La courbe représentative d'une fonction f admet en A=(a,f(a)) une tangente non verticale. Quelle grandeur est mesurée par f'(a) ?","a":["Le coefficient directeur de la tangente en A.","L'ordonnée à l'origine de la tangente.","La pente de la sécante joignant A à l'origine.","La courbure de la trajectoire."],"correct":0,"why":"La dérivée est la pente de la tangente au point considéré.","active":true,"family":"V2-C2-F202"},{"id":"V2-C2-F202-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Au point d'abscisse 3, la tangente à une courbe a pour équation \\(y=-2x+7\\). Quel renseignement fournit cette droite sur la fonction f ?","a":["\\(f'(3)=7\\).","\\(f'(3)=1\\).","\\(f'(3)=3\\).","\\(f'(3)=-2\\)."],"correct":3,"why":"Le coefficient de x est la pente de la tangente.","active":true,"family":"V2-C2-F202"},{"id":"V2-C2-F202-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une courbe de température présente une tangente horizontale au temps t0. Que peut-on conclure sur le taux instantané de variation, sans information supplémentaire ?","a":["La température vaut zéro en t0.","La température est nécessairement maximale en t0.","Il est nul en t0.","La température reste constante après t0."],"correct":2,"why":"Une tangente horizontale a une pente nulle ; cela ne garantit pas un extremum.","active":true,"family":"V2-C2-F202"},{"id":"V2-C2-F203-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soit f dérivable en a. Quelle équation représente exactement la tangente à son graphe au point (a,f(a)) ?","a":["\\(y=f'(a)(x-a)\\)","\\(y=f(a)+f'(a)(x-a)\\)","\\(y=f(a)+f'(a)x\\)","\\(y=f'(a)+f(a)(x-a)\\)"],"correct":1,"why":"La droite passe par (a,f(a)) et a pour pente f'(a).","active":true,"family":"V2-C2-F203"},{"id":"V2-C2-F203-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"On sait que \\(f(2)=5\\) et \\(f'(2)=-3\\). Quelle est l'équation de la tangente au point d'abscisse 2 ?","a":["\\(y=-3(x-2)\\)","\\(y=5-3(x-2)\\)","\\(y=5-3x\\)","\\(y=-3+5(x-2)\\)"],"correct":1,"why":"Substituer les valeurs dans la formule de la tangente.","active":true,"family":"V2-C2-F203"},{"id":"V2-C2-F203-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"La droite \\(y=4+2(x-1)\\) est tangente au graphe de f en x=1. Quelles valeurs de f(1) et f'(1) peut-on en déduire ?","a":["\\(f(1)=4,\\ f'(1)=2\\)","\\(f(1)=2,\\ f'(1)=4\\)","\\(f(1)=6,\\ f'(1)=2\\)","\\(f(1)=4,\\ f'(1)=6\\)"],"correct":0,"why":"Évaluer la droite au point de tangence et lire sa pente.","active":true,"family":"V2-C2-F203"},{"id":"V2-C2-F204-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle implication entre continuité et dérivabilité au point a est valable pour toute fonction réelle ?","a":["La continuité en a implique toujours la dérivabilité en a.","La continuité exclut la dérivabilité.","La dérivabilité est indépendante de la continuité.","La dérivabilité en a implique la continuité en a."],"correct":3,"why":"Une limite finie du taux d'accroissement impose la continuité.","active":true,"family":"V2-C2-F204"},{"id":"V2-C2-F204-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction présente une discontinuité en x=4. Quelle conclusion est certaine concernant sa dérivabilité à ce point ?","a":["Elle est dérivable si sa valeur en 4 est nulle.","Elle est dérivable si ses limites latérales sont finies.","Elle n'est pas dérivable en 4.","La discontinuité ne permet aucune conclusion sur la dérivabilité."],"correct":2,"why":"La contraposée de « dérivable implique continue » s'applique.","active":true,"family":"V2-C2-F204"},{"id":"V2-C2-F204-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant observe qu'une fonction est continue en a et conclut que f'(a) existe. Quelle objection est mathématiquement correcte ?","a":["Toute fonction continue est nécessairement constante près de a.","Une fonction continue possède toujours une tangente horizontale.","Une courbe continue peut présenter un angle en a, donc deux dérivées latérales différentes.","La continuité signifie que la fonction n'a pas de limite."],"correct":2,"why":"La continuité n'est qu'une condition nécessaire à la dérivabilité.","active":true,"family":"V2-C2-F204"},{"id":"V2-C2-F205-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Laquelle des fonctions suivantes est continue en zéro mais ne possède pas de dérivée en ce point ?","a":["\\(f(x)=x^2\\)","\\(f(x)=\\vert x\\vert\\)","\\(f(x)=e^x\\)","\\(f(x)=\\sin x\\)"],"correct":1,"why":"La valeur absolue a des pentes latérales -1 et 1 en zéro.","active":true,"family":"V2-C2-F205"},{"id":"V2-C2-F205-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=\\vert x-3\\vert\\), que valent les dérivées à gauche et à droite en x=3 ?","a":["Respectivement -1 et 1.","Respectivement 1 et -1.","Toutes deux égales à 0.","Toutes deux égales à 1."],"correct":0,"why":"De part et d'autre de 3, la fonction est affine de pente opposée.","active":true,"family":"V2-C2-F205"},{"id":"V2-C2-F205-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur est modélisée près de t=2 par \\(G(t)=1+2\\vert t-2\\vert\\). Quelle propriété échoue exactement au temps t=2 ?","a":["La continuité, car les limites latérales sont différentes.","L'existence de G(2), qui n'est pas défini.","La positivité de G, qui devient négative.","La dérivabilité, car les taux latéraux valent -2 et 2."],"correct":3,"why":"G(2)=1 et les limites latérales coïncident, mais les pentes diffèrent.","active":true,"family":"V2-C2-F205"},{"id":"V2-C2-F206-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soit u une fonction dérivable sur un intervalle I. Quelle règle donne la dérivée de \\(e^{u(x)}\\) ?","a":["\\(e^{u'(x)}\\)","\\(u(x)e^{u(x)}\\)","\\(e^{u(x)}/u'(x)\\)","\\(u'(x)e^{u(x)}\\)"],"correct":3,"why":"La règle de la chaîne multiplie la dérivée extérieure par celle de l'exposant.","active":true,"family":"V2-C2-F206"},{"id":"V2-C2-F206-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=e^{3x-1}\\), un étudiant propose \\(f'(x)=e^{3x-1}\\). Quel facteur manque dans son résultat ?","a":["Le facteur -1, terme constant de l'exposant.","Le facteur x, variable de l'exposant.","Le facteur 3, dérivée de l'exposant.","Le facteur e, base de l'exponentielle."],"correct":2,"why":"La dérivée de 3x-1 vaut 3.","active":true,"family":"V2-C2-F206"},{"id":"V2-C2-F206-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une quantité est décrite par \\(G(t)=e^{-kt}\\) avec k>0. Quelle expression de G' montre que G décroît ?","a":["\\(G'(t)=ke^{-kt}\\)","\\(G'(t)=-ke^{-kt}\\)","\\(G'(t)=-te^{-kt}\\)","\\(G'(t)=e^{-k}\\)"],"correct":1,"why":"La dérivée de -kt vaut -k et l'exponentielle est positive.","active":true,"family":"V2-C2-F206"},{"id":"V2-C2-F207-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soit u strictement positive et dérivable. Quelle est l'expression exacte de la dérivée de \\(\\ln(u(x))\\) ?","a":["\\(u'(x)/u(x)\\)","\\(1/u(x)\\)","\\(u(x)/u'(x)\\)","\\(u'(x)\\ln(u(x))\\)"],"correct":0,"why":"Appliquer la dérivation composée du logarithme.","active":true,"family":"V2-C2-F207"},{"id":"V2-C2-F207-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"On pose \\(g(x)=\\ln(5x+2)\\) sur son domaine ouvert. Quel résultat tient compte de la dérivée de l'argument ?","a":["\\(5/(5x+2)\\)","\\(1/(5x+2)\\)","\\(5\\ln(5x+2)\\)","\\((5x+2)/5\\)"],"correct":0,"why":"La dérivée de 5x+2 vaut 5.","active":true,"family":"V2-C2-F207"},{"id":"V2-C2-F207-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction est définie par \\(H(t)=\\ln(t^2+4)\\). Quelle est l'erreur dans le calcul \\(H'(t)=1/(t^2+4)\\) ?","a":["Il manque le facteur 4 au numérateur.","Il faut changer le signe du résultat.","Le dénominateur doit être remplacé par t².","Il manque le facteur 2t au numérateur."],"correct":3,"why":"La dérivée intérieure vaut 2t.","active":true,"family":"V2-C2-F207"},{"id":"V2-C2-F208-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soit u dérivable. Quelle expression donne la dérivée de \\(\\sin(u(x))\\) ?","a":["\\(-u'(x)\\cos(u(x))\\)","\\(\\cos(u'(x))\\)","\\(u'(x)\\cos(u(x))\\)","\\(u'(x)\\sin(u(x))\\)"],"correct":2,"why":"La dérivée du sinus est le cosinus et la règle de chaîne impose u'.","active":true,"family":"V2-C2-F208"},{"id":"V2-C2-F208-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour le modèle périodique \\(G(t)=\\sin(2t)\\), quelle expression représente sa vitesse instantanée ?","a":["\\(\\cos(2t)\\)","\\(2\\cos(2t)\\)","\\(-2\\sin(2t)\\)","\\(\\sin(2t)/2\\)"],"correct":1,"why":"La dérivée de l'argument 2t est 2.","active":true,"family":"V2-C2-F208"},{"id":"V2-C2-F208-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant dérive \\(\\sin(\\pi t)\\) et trouve \\(-\\pi\\cos(\\pi t)\\). Quelle correction convient ?","a":["Remplacer le cosinus par un sinus et conserver le signe moins.","Supprimer le signe moins : \\(\\pi\\cos(\\pi t)\\).","Diviser par π au lieu de multiplier.","Supprimer le facteur π."],"correct":1,"why":"Le signe moins appartient à la dérivée du cosinus, non du sinus.","active":true,"family":"V2-C2-F208"},{"id":"V2-C2-F209-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soient u et v dérivables sur I et α,β deux constantes. Quelle identité traduit la linéarité de la dérivation ?","a":["\\((\\alpha u+\\beta v)'=\\alpha u'+\\beta v'\\)","\\((\\alpha u+\\beta v)'=\\alpha\\beta u'v'\\)","\\((\\alpha u+\\beta v)'=u'+v'\\)","\\((\\alpha u+\\beta v)'=\\alpha u+\\beta v'\\)"],"correct":0,"why":"La dérivation conserve les combinaisons linéaires à coefficients constants.","active":true,"family":"V2-C2-F209"},{"id":"V2-C2-F209-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une quantité totale est la somme de deux contributions G1 et G2, toutes deux dérivables. Comment obtenir sa vitesse de variation instantanée ?","a":["Multiplier les vitesses G1' et G2'.","Additionner les valeurs G1 et G2 sans dériver.","Calculer la moyenne des deux vitesses.","Additionner les vitesses G1' et G2'."],"correct":3,"why":"La dérivée d'une somme est la somme des dérivées.","active":true,"family":"V2-C2-F209"},{"id":"V2-C2-F209-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"On connaît \\(u'(2)=3\\) et \\(v'(2)=-1\\). Quelle valeur obtient-on pour la dérivée de \\(2u-v\\) au point 2 ?","a":["\\(5\\)","\\(4\\)","\\(7\\)","\\(-2\\)"],"correct":2,"why":"Par linéarité : 2×3-(-1)=7.","active":true,"family":"V2-C2-F209"},{"id":"V2-C2-F210-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction est continue sur [a,b] et dérivable sur ]a,b[, avec a<b. Quelle hypothèse supplémentaire permet d'appliquer le théorème de Rolle ?","a":["\\(f'(a)=f'(b)\\)","\\(f(a)=-f(b)\\)","\\(f(a)=f(b)\\)","\\(f(a)f(b)<0\\)"],"correct":2,"why":"Rolle exige des valeurs égales aux bornes.","active":true,"family":"V2-C2-F210"},{"id":"V2-C2-F210-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction f est continue sur [0,4], dérivable sur ]0,4[, et vérifie f(0)=2 et f(4)=5. Quelle hypothèse de Rolle n'est pas satisfaite ?","a":["La continuité sur le segment.","L'égalité des images aux deux bornes.","La dérivabilité sur l'intérieur.","L'existence d'un intervalle non vide."],"correct":1,"why":"Les images 2 et 5 sont distinctes.","active":true,"family":"V2-C2-F210"},{"id":"V2-C2-F210-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^2\\) sur [-2,2], quelle vérification complète permet d'appliquer le théorème de Rolle ?","a":["f est polynomiale et f(-2)=f(2)=4.","f est positive et f(0)=0.","f(-2) et f(2) ont des signes opposés.","La dérivée est nulle en chaque point du segment."],"correct":0,"why":"La fonction est continue et dérivable et ses valeurs aux bornes coïncident.","active":true,"family":"V2-C2-F210"},{"id":"V2-C2-F211-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Sous les hypothèses du théorème de Rolle sur [a,b], quelle conclusion est garantie ?","a":["Il existe \\(c\\in]a,b[\\) tel que \\(f(c)=0\\).","Pour tout c dans ]a,b[, f'(c)=0.","Il existe c tel que f''(c)=0.","Il existe \\(c\\in]a,b[\\) tel que \\(f'(c)=0\\)."],"correct":3,"why":"Rolle garantit au moins une tangente horizontale à l'intérieur du segment.","active":true,"family":"V2-C2-F211"},{"id":"V2-C2-F211-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur différentiable sur ]0,10[ et continue sur [0,10] retrouve au temps 10 sa valeur initiale. Quelle conséquence est garantie ?","a":["La grandeur elle-même s'annule au moins une fois.","La grandeur est constante sur toute la période.","Sa vitesse est maximale au temps 5.","Sa vitesse instantanée s'annule au moins une fois entre 0 et 10."],"correct":3,"why":"Les hypothèses de Rolle sont vérifiées.","active":true,"family":"V2-C2-F211"},{"id":"V2-C2-F211-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant invoque Rolle pour affirmer qu'il existe exactement un point c où f'(c)=0. Pourquoi cette affirmation est-elle trop forte ?","a":["Rolle ne garantit aucun point intérieur.","Rolle exige que f soit strictement monotone.","Le théorème garantit l'existence, pas l'unicité.","Rolle concerne uniquement f(c)=0."],"correct":2,"why":"Une fonction constante vérifie Rolle et sa dérivée est nulle partout.","active":true,"family":"V2-C2-F211"},{"id":"V2-C2-F212-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soit f dérivable sur un intervalle I avec f'(x)≥0 pour tout x de I. Quelle conclusion est toujours justifiée ?","a":["f est strictement croissante sur I dans tous les cas.","f est croissante au sens large sur I.","f est décroissante sur I.","f est constante sur I dans tous les cas."],"correct":1,"why":"Le TAF garantit que f(b)-f(a)≥0 si b>a.","active":true,"family":"V2-C2-F212"},{"id":"V2-C2-F212-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"La dérivée d'une grandeur est strictement négative sur un intervalle de temps. Que signifie ce signe pour la grandeur ?","a":["Elle est strictement décroissante sur cet intervalle.","Elle est négative à chaque instant.","Elle devient nécessairement nulle avant la fin de l'intervalle.","Elle est constante car son taux de variation est négatif."],"correct":0,"why":"Le signe de la dérivée détermine le sens de variation, non le signe de la grandeur.","active":true,"family":"V2-C2-F212"},{"id":"V2-C2-F212-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant déduit de \\(f'(x)\\ge0\\) que \\(f(x)\\ge0\\). Quelle réponse rectifie son raisonnement ?","a":["Une dérivée non négative assure la croissance, mais pas la positivité des valeurs.","La dérivée non négative implique que f est décroissante.","La dérivée non négative impose f(0)=0.","La dérivée non négative implique toujours une valeur maximale."],"correct":0,"why":"Par exemple, f(x)=x-10 est croissante mais négative pour x<10.","active":true,"family":"V2-C2-F212"},{"id":"V2-C2-F213-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une fonction deux fois dérivable sur I, quelle condition sur f'' garantit la convexité sur I ?","a":["\\(f'(x)\\ge0\\) sur I.","\\(f''(x)\\le0\\) sur I.","\\(f(x)\\ge0\\) sur I.","\\(f''(x)\\ge0\\) sur I."],"correct":3,"why":"Une dérivée seconde non négative rend la dérivée première croissante.","active":true,"family":"V2-C2-F213"},{"id":"V2-C2-F213-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur vérifie \\(G'(t)>0\\) et \\(G''(t)<0\\) pendant une période. Quelle interprétation est correcte ?","a":["Elle diminue, mais sa vitesse augmente.","Elle augmente à vitesse croissante.","Elle augmente, mais sa vitesse de croissance diminue.","Elle reste constante puisque G'' est négative."],"correct":2,"why":"Le signe de G' indique la croissance ; G''<0 indique la concavité.","active":true,"family":"V2-C2-F213"},{"id":"V2-C2-F213-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant affirme que la fonction \\(f(x)=-x^2+10\\) est convexe car elle est positive près de zéro. Quelle vérification corrige l'affirmation ?","a":["f'(x)=-2x : f est convexe parce que f'(0)=0.","f''(x)=-2<0 : f est concave.","f(0)=10 : f est nécessairement convexe.","f''(0)=0 : la convexité est indéterminée."],"correct":1,"why":"La convexité dépend de la dérivée seconde, non du signe de la fonction.","active":true,"family":"V2-C2-F213"},{"id":"V2-C2-F214-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle propriété caractérise un point d'inflexion d'une courbe deux fois dérivable ?","a":["Une tangente nécessairement horizontale.","Un changement de convexité de part et d'autre du point.","Un maximum global de la fonction.","Une intersection nécessaire avec l'axe des abscisses."],"correct":1,"why":"L'inflexion correspond au passage de convexe à concave ou inversement.","active":true,"family":"V2-C2-F214"},{"id":"V2-C2-F214-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^4\\), on constate f''(0)=0. Peut-on en déduire un point d'inflexion en zéro ?","a":["Non, car f''(x)=12x² reste non négative des deux côtés.","Oui, car l'annulation de f'' suffit toujours.","Oui, car f'(0)=0.","Non, car la fonction n'est pas dérivable."],"correct":0,"why":"La convexité ne change pas au voisinage de zéro.","active":true,"family":"V2-C2-F214"},{"id":"V2-C2-F214-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"La dérivée seconde d'une fonction vaut \\(f''(x)=6(x-2)\\). Quelle information en déduit-on autour de x=2 ?","a":["La courbe passe de convexe à concave en x=2.","La fonction est maximale en x=2.","La fonction s'annule nécessairement en x=2.","La courbe passe de concave à convexe en x=2."],"correct":3,"why":"La dérivée seconde passe du signe négatif au signe positif.","active":true,"family":"V2-C2-F214"},{"id":"V2-C2-F215-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction est dérivable en a. Quelle approximation linéaire décrit sa variation pour un petit déplacement h ?","a":["\\(f(a+h)-f(a)\\approx h f(a)\\)","\\(f(a+h)-f(a)\\approx f'(a)/h\\)","\\(f(a+h)-f(a)\\approx hf'(a)\\)","\\(f(a+h)-f(a)\\approx h^2f''(a)\\)"],"correct":2,"why":"Le taux d'accroissement tend vers f'(a).","active":true,"family":"V2-C2-F215"},{"id":"V2-C2-F215-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur vaut G(3)=20 et G'(3)=-2 unités par heure. Quelle approximation de G(3,1) donne la tangente ?","a":["20,2","18","19,8","21,8"],"correct":2,"why":"G(3+0,1)≈20-2×0,1.","active":true,"family":"V2-C2-F215"},{"id":"V2-C2-F215-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant approche \\(f(a+h)\\) par \\(hf'(a)\\). Quelle quantité a-t-il oubliée ?","a":["La dérivée seconde f''(a) dans tous les cas.","La valeur initiale f(a).","Le quotient f'(a)/h.","Le facteur h²."],"correct":1,"why":"Le modèle affine complet est f(a)+hf'(a).","active":true,"family":"V2-C2-F215"},{"id":"V2-C2-M201-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=(x^2+4)e^{-x}\\). Quelle expression de f' résulte de l'application correcte de la règle du produit ?","a":["\\((-x^2+2x-4)e^{-x}\\)","\\(2xe^{-x}\\)","\\((-x^2-2x-4)e^{-x}\\)","\\((x^2+2x+4)e^{-x}\\)"],"correct":0,"why":"Dériver les deux facteurs et additionner les deux contributions.","active":true,"family":"V2-C2-M201"},{"id":"V2-C2-M201-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle \\(G(t)=(t+3)e^{-2t}\\) comporte deux facteurs variables. Un étudiant ne dérive que le premier. Quel est le résultat complet ?","a":["\\(G'(t)=e^{-2t}\\)","\\(G'(t)=-2(t+3)e^{-2t}\\)","\\(G'(t)=(2t+7)e^{-2t}\\)","\\(G'(t)=(-2t-5)e^{-2t}\\)"],"correct":3,"why":"La dérivée de t+3 vaut 1 et celle de e^-2t vaut -2e^-2t.","active":true,"family":"V2-C2-M201"},{"id":"V2-C2-M201-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^2\\ln x\\), x>0, quelle expression simplifiée de f' tient compte des deux facteurs ?","a":["\\(2x\\ln x\\)","\\(x\\)","\\(2x/x\\)","\\(2x\\ln x+x\\)"],"correct":3,"why":"Le terme x²/x vaut x et s'ajoute à 2x ln x.","active":true,"family":"V2-C2-M201"},{"id":"V2-C2-M202-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"On sait que \\(f'(x)=-(x-2)^2e^{-x}\\) sur R. Quel tableau de variation qualitatif est correct ?","a":["f décroît puis croît en 2.","f croît puis décroît en 2.","f décroît sur R sans changer de sens en 2.","f est constante sur R."],"correct":2,"why":"La dérivée est négative sauf en 2 et ne change pas de signe.","active":true,"family":"V2-C2-M202"},{"id":"V2-C2-M202-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction dérivable possède une dérivée \\(g'(t)=(t-4)^2\\). Pourquoi le point t=4 n'est-il pas un extremum local ?","a":["g' change de signe en 4.","g' reste positive de part et d'autre de 4.","g(4) est nécessairement nulle.","g' est négative après 4."],"correct":1,"why":"Une dérivée nulle isolée sans changement de signe n'implique pas un extremum.","active":true,"family":"V2-C2-M202"},{"id":"V2-C2-M202-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=-x^3\\), un étudiant annonce un maximum en zéro puisque f'(0)=0. Quelle étude de signe réfute ce résultat ?","a":["\\(f'(x)=-3x^2\\) est négative de part et d'autre de zéro : f reste décroissante.","f' est positive pour x<0 et négative pour x>0.","f' est négative pour x<0 et positive pour x>0.","f' est identiquement nulle."],"correct":0,"why":"Le carré ne change pas de signe.","active":true,"family":"V2-C2-M202"},{"id":"V2-C2-M203-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=e^{3x}\\), quelle est l'expression de la dérivée n-ième pour tout entier n≥0 ?","a":["\\(3^ne^{3x}\\)","\\(3ne^{3x}\\)","\\(e^{3nx}\\)","\\(n^3e^{3x}\\)"],"correct":0,"why":"Chaque dérivation multiplie le résultat par 3.","active":true,"family":"V2-C2-M203"},{"id":"V2-C2-M203-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une quantité décroît selon \\(G(t)=20e^{-2t}\\). Quelle expression donne sa dérivée troisième ?","a":["\\(160e^{-2t}\\)","\\(-40e^{-2t}\\)","\\(-120e^{-2t}\\)","\\(-160e^{-2t}\\)"],"correct":3,"why":"Le facteur (-2)^3 vaut -8.","active":true,"family":"V2-C2-M203"},{"id":"V2-C2-M203-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=e^{-4x}\\), quelle propriété distingue les dérivées d'ordre pair et impair ?","a":["Toutes les dérivées d'ordre positif sont négatives.","Les dérivées paires sont nulles.","Les dérivées d'ordre pair sont positives et celles d'ordre impair négatives.","Toutes les dérivées sont positives."],"correct":2,"why":"f^(n)=(-4)^n e^-4x.","active":true,"family":"V2-C2-M203"},{"id":"V2-C2-M204-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soient u et v dérivables, v non nulle sur I. Quelle formule donne la dérivée de leur quotient ?","a":["\\((u'v+uv')/v^2\\)","\\((u'v-uv')/v^2\\)","\\((uv'-u'v)/v^2\\)","\\(u'/v'\\)"],"correct":1,"why":"La règle du quotient impose un signe moins et le carré au dénominateur.","active":true,"family":"V2-C2-M204"},{"id":"V2-C2-M204-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=(2x+1)/(x+3)\\) pour x≠-3. Quelle est sa dérivée simplifiée ?","a":["\\((4x+7)/(x+3)^2\\)","\\(5/(x+3)^2\\)","\\(2/(x+3)\\)","\\(-5/(x+3)^2\\)"],"correct":1,"why":"Le numérateur vaut 2(x+3)-(2x+1)=5.","active":true,"family":"V2-C2-M204"},{"id":"V2-C2-M204-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une mesure suit \\(G(t)=12/(1+3t)\\). Quel calcul justifie que G décroît pour t≥0 ?","a":["\\(G'(t)=-36/(1+3t)^2<0\\).","\\(G'(t)=36/(1+3t)^2>0\\).","\\(G'(t)=-12/(1+3t)<0\\).","\\(G'(t)=0\\), car le numérateur est constant."],"correct":0,"why":"Dériver l'inverse du dénominateur.","active":true,"family":"V2-C2-M204"},{"id":"V2-C2-M205-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit f continue sur [a,b], dérivable sur ]a,b[, avec a<b. Quelle égalité est garantie par le théorème des accroissements finis ?","a":["Il existe c tel que \\(f'(c)=f(b)-f(a)\\).","Il existe c tel que \\(f(c)=(f'(b)-f'(a))/(b-a)\\).","Il existe c tel que \\(f'(c)=0\\), sans autre hypothèse.","Il existe c dans ]a,b[ tel que \\(f'(c)=(f(b)-f(a))/(b-a)\\)."],"correct":3,"why":"La pente instantanée coïncide au moins une fois avec la pente moyenne.","active":true,"family":"V2-C2-M205"},{"id":"V2-C2-M205-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une grandeur continue sur [2,6] et dérivable à l'intérieur passe de 14 à 30 unités. Quelle valeur de la vitesse instantanée est nécessairement atteinte à un temps intermédiaire ?","a":["16 unités par unité de temps.","8 unités par unité de temps.","4 unités par unité de temps.","22 unités par unité de temps."],"correct":2,"why":"Le taux moyen est (30-14)/(6-2)=4.","active":true,"family":"V2-C2-M205"},{"id":"V2-C2-M205-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant applique le TAF à \\(f(x)=\\vert x-1\\vert\\) sur [0,2]. Quelle hypothèse empêche de conclure ?","a":["La continuité sur [0,2].","L'égalité des valeurs aux bornes, obligatoire pour le TAF.","La dérivabilité en x=1, point intérieur du segment.","La positivité de f sur le segment."],"correct":2,"why":"Le point anguleux intérieur empêche l'application du TAF.","active":true,"family":"V2-C2-M205"},{"id":"V2-C2-M206-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^2\\) sur [2,6], quel point c satisfait l'égalité du TAF ?","a":["\\(c=2\\)","\\(c=4\\)","\\(c=6\\)","\\(c=8\\)"],"correct":1,"why":"La pente moyenne est (36-4)/4=8 ; f'(c)=2c=8.","active":true,"family":"V2-C2-M206"},{"id":"V2-C2-M206-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Sur [1,4], une fonction est donnée par \\(f(x)=x^2+2x\\). Quelle valeur de c égalise la pente de la tangente et celle de la sécante aux bornes ?","a":["\\(c=5/2\\)","\\(c=7/2\\)","\\(c=2\\)","\\(c=1\\)"],"correct":0,"why":"La pente moyenne vaut 7 et f'(c)=2c+2.","active":true,"family":"V2-C2-M206"},{"id":"V2-C2-M206-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^2\\) sur [a,b] avec a<b, quelle expression générale du point garanti par le TAF obtient-on ?","a":["\\(c=b-a\\)","\\(c=(b-a)/2\\)","\\(c=ab\\)","\\(c=(a+b)/2\\)"],"correct":3,"why":"La pente moyenne vaut a+b, et la dérivée vaut 2c.","active":true,"family":"V2-C2-M206"},{"id":"V2-C2-M207-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit f vérifiant \\(2\\le f'(x)\\le5\\) sur ]1,4[ et continue sur [1,4]. Quel encadrement le plus précis de f(4)-f(1) fournit le TAF ?","a":["\\(2\\le f(4)-f(1)\\le5\\)","\\(3\\le f(4)-f(1)\\le7\\)","\\(2/3\\le f(4)-f(1)\\le5/3\\)","\\(6\\le f(4)-f(1)\\le15\\)"],"correct":3,"why":"Multiplier les bornes de la dérivée par la longueur 3.","active":true,"family":"V2-C2-M207"},{"id":"V2-C2-M207-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une grandeur augmente avec un taux compris entre 3 et 7 unités/h pendant 2 h. Quel intervalle contient nécessairement son accroissement total, sous les hypothèses usuelles de continuité et dérivabilité ?","a":["[3,7] unités.","[1,5] unités.","[6,14] unités.","[5,9] unités."],"correct":2,"why":"Le taux moyen est compris entre 3 et 7.","active":true,"family":"V2-C2-M207"},{"id":"V2-C2-M207-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction dérivable satisfait \\(\\vert f'(x)\\vert\\le4\\) sur un intervalle. Quelle borne optimale déduite du TAF s'applique à deux points x,y de cet intervalle ?","a":["\\(\\vert f(y)-f(x)\\vert\\le4\\) indépendamment de x,y.","\\(\\vert f(y)-f(x)\\vert\\le4\\vert y-x\\vert\\)","\\(\\vert f(y)-f(x)\\vert\\le\\vert y-x\\vert/4\\)","\\(\\vert f(y)-f(x)\\vert=4\\)"],"correct":1,"why":"Appliquer le TAF puis prendre les valeurs absolues.","active":true,"family":"V2-C2-M207"},{"id":"V2-C2-M208-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant cherche les extrema d'une fonction dérivable sur un intervalle ouvert. Pourquoi l'équation \\(f'(a)=0\\) ne suffit-elle pas à identifier un extremum ?","a":["Il faut notamment étudier le signe de f' autour de a ou employer un autre critère suffisant.","Tout point stationnaire est nécessairement un maximum.","Un extremum exige toujours f''(a)=0.","Une fonction dérivable ne peut pas avoir d'extremum."],"correct":0,"why":"L'annulation de la dérivée est nécessaire à un extremum intérieur mais pas suffisante.","active":true,"family":"V2-C2-M208"},{"id":"V2-C2-M208-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Parmi les fonctions suivantes, laquelle a un point stationnaire en zéro sans extremum local ?","a":["\\(f(x)=x^3\\)","\\(f(x)=x^2\\)","\\(f(x)=-x^2\\)","\\(f(x)=x^4\\)"],"correct":0,"why":"x³ est strictement croissante autour de zéro malgré f'(0)=0.","active":true,"family":"V2-C2-M208"},{"id":"V2-C2-M208-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une dérivée passe du signe négatif au signe positif en un point intérieur a. Quelle conclusion sur f est alors justifiée ?","a":["f possède un maximum local strict en a.","f possède nécessairement un point d'inflexion en a.","f est constante au voisinage de a.","f possède un minimum local strict en a."],"correct":3,"why":"La fonction décroît avant a et croît après a.","active":true,"family":"V2-C2-M208"},{"id":"V2-C2-M209-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-12x\\), quels extrema locaux obtient-on après étude du signe de la dérivée ?","a":["Maximum en x=2, de valeur -16 ; minimum en x=-2, de valeur 16.","Maximum en x=0, de valeur 0 ; aucun minimum.","Maximum en x=-2, de valeur 16 ; minimum en x=2, de valeur -16.","Aucun extremum, car f est un polynôme de degré impair."],"correct":2,"why":"f'=3(x²-4), positive hors de [-2,2] et négative entre les racines.","active":true,"family":"V2-C2-M209"},{"id":"V2-C2-M209-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-27x\\), un étudiant trouve les points stationnaires ±3. Quelle classification est exacte ?","a":["Minimum local en -3 ; maximum local en 3.","Maximum local en -3 ; minimum local en 3.","Deux maxima locaux.","Deux minima locaux."],"correct":1,"why":"La dérivée passe de + à - en -3 puis de - à + en 3.","active":true,"family":"V2-C2-M209"},{"id":"V2-C2-M209-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(h(x)=-x^3+3x\\). Quelles sont les valeurs des extrema locaux et leurs abscisses ?","a":["Maximum 2 en -1 ; minimum -2 en 1.","Minimum -2 en -1 ; maximum 2 en 1.","Minimum 0 en 0 ; maximum 3 en 1.","Aucun extremum local."],"correct":1,"why":"h'=3(1-x²), négative hors de [-1,1] et positive entre les racines.","active":true,"family":"V2-C2-M209"},{"id":"V2-C2-M210-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-6x^2+5x\\), quelle abscisse correspond à un changement de convexité ?","a":["\\(x=2\\)","\\(x=0\\)","\\(x=6\\)","\\(x=5\\)"],"correct":0,"why":"f''(x)=6x-12 change de signe en 2.","active":true,"family":"V2-C2-M210"},{"id":"V2-C2-M210-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(g(x)=2x^3+6x^2+1\\). Quelle description de sa convexité est exacte ?","a":["Convexe pour x<-1 et concave pour x>-1.","Convexe sur R entier.","Concave sur R entier.","Concave pour x<-1 et convexe pour x>-1."],"correct":3,"why":"g''=12x+12.","active":true,"family":"V2-C2-M210"},{"id":"V2-C2-M210-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-3x+2\\), quelles sont les coordonnées du point d'inflexion ?","a":["\\((0,0)\\)","\\((1,0)\\)","\\((0,2)\\)","\\((-1,4)\\)"],"correct":2,"why":"f''=6x change de signe en zéro, et f(0)=2.","active":true,"family":"V2-C2-M210"},{"id":"V2-C2-M211-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit f deux fois dérivable, f'(a)=0 et f''(a)>0. Quelle conclusion est garantie ?","a":["Un maximum local strict en a.","Un point d'inflexion obligatoire.","Un minimum local strict en a.","Un minimum global nécessairement."],"correct":2,"why":"Le critère de la dérivée seconde garantit un minimum local strict.","active":true,"family":"V2-C2-M211"},{"id":"V2-C2-M211-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction possède f'(2)=0 et f''(2)=-6. Quel diagnostic local est correct ?","a":["Un minimum local strict en 2.","Un maximum local strict en 2.","Un point d'inflexion en 2.","Aucun diagnostic possible."],"correct":1,"why":"La dérivée seconde négative au point stationnaire donne un maximum local strict.","active":true,"family":"V2-C2-M211"},{"id":"V2-C2-M211-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^4\\) et \\(g(x)=-x^4\\), les dérivées premières et secondes sont nulles en zéro. Quelle conclusion illustre cet exemple ?","a":["Lorsque f''(a)=0, le critère de la dérivée seconde ne tranche pas.","Lorsque f''(a)=0, il n'existe aucun extremum.","Les deux fonctions ont nécessairement un minimum.","Les deux fonctions ont nécessairement un maximum."],"correct":0,"why":"x⁴ a un minimum, -x⁴ un maximum malgré le même test nul.","active":true,"family":"V2-C2-M211"},{"id":"V2-C2-M212-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\sqrt{x}\\) pour x>0. Quelle équation donne la tangente au point d'abscisse 4 ?","a":["\\(y=2+(x-4)/2\\)","\\(y=(x-4)/4\\)","\\(y=4+(x-2)/4\\)","\\(y=2+(x-4)/4\\)"],"correct":3,"why":"f(4)=2 et f'(4)=1/4.","active":true,"family":"V2-C2-M212"},{"id":"V2-C2-M212-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"On approche \\(\\sqrt{9,3}\\) par la tangente à la fonction racine en 9. Quelle approximation obtient-on ?","a":["\\(3,15\\)","\\(3,3\\)","\\(2,95\\)","\\(3,05\\)"],"correct":3,"why":"f'(9)=1/6 et le déplacement vaut 0,3.","active":true,"family":"V2-C2-M212"},{"id":"V2-C2-M212-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=\\ln x\\), quelle approximation locale de f(2+h) au premier ordre découle de la dérivée ?","a":["\\(\\ln2+2h\\)","\\(h/2\\)","\\(\\ln2+h/2\\)","\\(\\ln(2)+h^2/2\\)"],"correct":2,"why":"f(2)=ln2 et f'(2)=1/2.","active":true,"family":"V2-C2-M212"},{"id":"V2-C2-M213-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\cos(2x)\\). Quel développement limité d'ordre 2 en zéro est exact ?","a":["\\(1-x^2/2+o(x^2)\\)","\\(1-2x^2+o(x^2)\\)","\\(1+2x^2+o(x^2)\\)","\\(1-2x+o(x^2)\\)"],"correct":1,"why":"Remplacer x par 2x dans 1-x²/2+o(x²).","active":true,"family":"V2-C2-M213"},{"id":"V2-C2-M213-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=\\ln(1+3x)\\), quelle expression donne son développement limité d'ordre 2 au voisinage de zéro ?","a":["\\(3x-9x^2/2+o(x^2)\\)","\\(3x+9x^2/2+o(x^2)\\)","\\(1+3x-9x^2/2+o(x^2)\\)","\\(3x-3x^2/2+o(x^2)\\)"],"correct":0,"why":"Substituer 3x dans le développement du logarithme.","active":true,"family":"V2-C2-M213"},{"id":"V2-C2-M213-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant écrit \\(e^{-2x}=1-2x-2x^2+o(x^2)\\). Quelle correction faut-il apporter ?","a":["Le coefficient de x² est +2, car (-2)²/2!=2.","Le coefficient linéaire doit être +2.","Le terme constant doit être zéro.","Le coefficient de x² doit être -4."],"correct":0,"why":"Le carré du coefficient intérieur est positif.","active":true,"family":"V2-C2-M213"},{"id":"V2-C2-M214-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Dans \\(f(a+h)=P_2(h)+o(h^2)\\), que signifie rigoureusement que le reste r(h) est un petit o de h² ?","a":["\\(\\lim_{h\\to0}r(h)=1\\)","\\(r(h)=h^2\\) pour tout h.","\\(r(h)=0\\) pour tout h suffisamment petit.","\\(\\lim_{h\\to0}r(h)/h^2=0\\)"],"correct":3,"why":"Le rapport du reste à h² tend vers zéro.","active":true,"family":"V2-C2-M214"},{"id":"V2-C2-M214-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un reste vaut \\(r(h)=5h^3\\). Quelle propriété justifie qu'il est négligeable à l'ordre 2 ?","a":["\\(r(h)/h^2=5\\)","\\(r(h)=0\\) pour tout h.","\\(r(h)/h^2=5h\\to0\\)","\\(r(h)/h^2\\to+\\infty\\)"],"correct":2,"why":"La puissance du reste est strictement supérieure à deux.","active":true,"family":"V2-C2-M214"},{"id":"V2-C2-M214-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant remplace \\(o(h^2)\\) par \\(O(h^2)\\) en affirmant que les deux notations sont équivalentes. Quel contre-exemple suffit ?","a":["\\(r(h)=h^3\\) : le rapport tend vers zéro, donc pas O(h²).","\\(r(h)=h^2\\) : le rapport vaut 1, donc O(h²) mais pas o(h²).","\\(r(h)=0\\) : le rapport est nul, donc pas o(h²).","\\(r(h)=h^2\\) : le rapport vaut 0, donc o(h²)."],"correct":1,"why":"La notation O impose seulement la bornitude du rapport ; o impose sa convergence vers zéro.","active":true,"family":"V2-C2-M214"},{"id":"V2-C2-M215-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction vérifie \\(f'(x)=3(x-1)(x+2)\\). Sur quels intervalles ouverts est-elle strictement croissante ?","a":["\\(]-2,1[\\) uniquement.","\\(]-\\infty,-2[\\) et \\(]1,+\\infty[\\).","\\(]-\\infty,1[\\) uniquement.","\\(]-2,+\\infty[\\) uniquement."],"correct":1,"why":"Le produit de facteurs est positif en dehors de ses racines.","active":true,"family":"V2-C2-M215"},{"id":"V2-C2-M215-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(g'(x)=-(x-3)(x+1)\\). Quel sens de variation g possède-t-elle sur ]-1,3[ ?","a":["Strictement croissante.","Strictement décroissante.","Constante.","Croissante puis décroissante au milieu de l'intervalle."],"correct":0,"why":"Le produit (x-3)(x+1) est négatif sur cet intervalle.","active":true,"family":"V2-C2-M215"},{"id":"V2-C2-M215-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction dérivable a une dérivée \\(h'(x)=(x-2)(x-5)\\). À quels points h possède-t-elle respectivement un maximum et un minimum locaux ?","a":["Minimum en 2 et maximum en 5.","Deux maxima en 2 et 5.","Deux minima en 2 et 5.","Maximum en 2 et minimum en 5."],"correct":3,"why":"La dérivée passe de + à - en 2, puis de - à + en 5.","active":true,"family":"V2-C2-M215"}]);
